do $$
declare missing int; extra int;
begin
  delete from ten280_bot.alerts where mode='backtest' and run_id='g5';
  perform ten280_bot.load_ticks('2026-09-11 05:18:09.860093+00', '2026-09-25 05:18:09.860093+00');
  perform ten280_bot.scan('2026-09-18 05:18:09.860093+00', '2026-09-20 05:18:09.860093+00', 5, 'backtest', 'g5', interval '10 minutes', 1.30);
  select count(*) into missing from ten280_bot.alerts o where o.mode='backtest' and o.run_id='bt5' and o.eval_at <= '2026-09-20 05:18:09.860093+00'
     and not exists (select 1 from ten280_bot.alerts n where n.mode='backtest' and n.run_id='g5' and n.fixture_id=o.fixture_id and n.side_id=o.side_id and n.eval_at=o.eval_at and n.cur_price=o.cur_price and n.ref_price=o.ref_price);
  select count(*) into extra from ten280_bot.alerts n where n.mode='backtest' and n.run_id='g5'
     and not exists (select 1 from ten280_bot.alerts o where o.mode='backtest' and o.run_id='bt5' and o.fixture_id=n.fixture_id and o.side_id=n.side_id and o.eval_at=n.eval_at and o.cur_price=n.cur_price and o.ref_price=n.ref_price);
  if missing <> 0 or extra <> 0 or (select count(*) from ten280_bot.alerts where mode='backtest' and run_id='g5') = 0 then
    raise exception 'REGRESSION GATE: vs the original 5%% backtest (18-20 Sep): % missing, % extra', missing, extra;
  end if;
  raise notice 'REGRESSION GATE PASS';
end $$;

