do $$ declare rid bigint; a ten280_bot.alerts; msg text; begin
  perform pg_advisory_xact_lock(280281);
  if exists (select 1 from ten280_bot.events where kind = 'format_test_v3') then return; end if;
  select * into a from ten280_bot.alerts where id = 1942;
  if a.id is null then raise exception 'alert 1942 missing'; end if;
  msg := '🧪 FORMAT TEST — the 07:09 UTC alert re-sent in the new layout (not a new move):' || chr(10) || chr(10) || ten280_bot.render(a, coalesce(a.sent_at, a.eval_at));
  rid := ten280_bot.send(msg);
  insert into ten280_bot.events (kind, detail, net_request_id, delivery) values ('format_test_v3', jsonb_build_object('alert_id', a.id, 'text', msg), rid, case when rid is null then 'unsent: no vault secret' else 'queued' end);
end $$; select id, kind, delivery from ten280_bot.events where kind = 'format_test_v3'
